function throttle(fn, ms) {
  let lastFired = -Infinity;       // when the last fn() call happened, on fake clock
  const api = function (...args) {
    if (api._now - lastFired >= ms) {
      lastFired = api._now;
      fn(...args);                 // leading edge: fire immediately
    }
    // else: drop this call silently
  };
  api._now = 0;
  api.tick = (delta) => { api._now += delta; };
  return api;
}

